cd /tmp/sv-d8ea4daaca5a4cf090003606139bf3f5/moderate-msbuild-properties && dotnet package list --format json 2>/dev/null | python3 -c "
import sys, json
data = json.load(sys.stdin)
for p in data['projects']:
    name = p['path'].split('/')[-1]
    for fw in p['frameworks']:
        for pkg in fw['topLevelPackages']:
            print(f'{name} | {pkg[\"id\"]} | {pkg[\"resolvedVersion\"]}')
"

